/* @lc app=leetcode id=4023 lang=kotlin */ class Solution { fun elevatorRequests(n: Int, start: Int, requests: IntArray): Long = requests.filter { it < start }.sortedDescending().let { lp -> requests.filter { it > start }.sorted().let { rp -> (lp.size + rp.size).let { M -> { i: Int -> if (i == 0) start else lp[i - 1] }.let { pl -> { j: Int -> if (j == 0) start else rp[j - 1] }.let { pr -> Array(lp.size + 1) { Array(rp.size + 1) { LongArray(2) { Long.MAX_VALUE / 4 } } }.also { g -> g[0][0].fill(0L) }.also { g -> (0..lp.size).forEach { i -> (0..rp.size).forEach { j -> g[i][j].let { cell -> (if (i >= 1) minOf(g[i - 1][j][0] + Math.abs(pl(i - 1) - pl(i)).toLong() * (M - i + 1 - j), g[i - 1][j][1] + Math.abs(pr(j) - pl(i)).toLong() * (M - i + 1 - j)) else cell[0]).let { v0 -> (if (j >= 1) minOf(g[i][j - 1][1] + Math.abs(pr(j - 1) - pr(j)).toLong() * (M - i - j + 1), g[i][j - 1][0] + Math.abs(pl(i) - pr(j)).toLong() * (M - i - j + 1)) else cell[1]).let { v1 -> cell.set(0, v0).also { cell.set(1, v1) } } } } } } }.let { g -> minOf(g[lp.size][rp.size][0], g[lp.size][rp.size][1]) } } } } } } }